@Override
public boolean isDurationEffectTick(int duration, int amplifier) {
  return duration == 1;
}

@Override
public void applyEffectTick(LivingEntity living, int amplifier) {
  ModDataNBT data = PersistentDataCapability.getOrWarn(living);
  if (data.contains(KEY, Tag.TAG_COMPOUND)) {
    CompoundTag tag = data.getCompound(KEY);
    ResourceLocation dimension = ResourceLocation.tryParse(tag.getString("dimension"));
    // no teleporting if you switched dimensions
    // TODO: look into cross dimensional teleport, its doable with entity#teleportTo
    if (dimension != null && dimension.equals(living.level().dimension().location())) {
      BlockPos pos = NbtUtils.readBlockPos(tag);
      TeleportHelper.tryTeleport(new ReturningTeleportEvent(living, pos.getX(), pos.getY(), pos.getZ()));
    }
  }
}

public ReturningEffect() {
  super(MobEffectCategory.NEUTRAL, 0xa92dff, true);
  MinecraftForge.EVENT_BUS.addListener(this::onEffectAdded);
}

@Override
public InteractionResult use(BlockState state, Level world, BlockPos pos, Player player, InteractionHand handIn, BlockHitResult hit) {
  InteractionResult result = this.eatSlice(world, pos, state, player);
  if (result.consumesAction()) {
    return result;
  }
  if (world.isClientSide() && player.getItemInHand(handIn).isEmpty()) {
    return InteractionResult.CONSUME;
  }
  return InteractionResult.PASS;
}

private InteractionResult eatSlice(LevelAccessor world, BlockPos pos, BlockState state, Player player) {
  if (!player.canEat(false) && !food.canAlwaysEat()) {
    return InteractionResult.PASS;
  }
  // repurpose fast eating, will mean no eating if we have the effect
  if (combination == EffectCombination.BLOCK && hasAllEffects(player)) {
    return InteractionResult.PASS;
  }
  player.awardStat(Stats.EAT_CAKE_SLICE);
  // apply food stats
  player.getFoodData().eat(food.getNutrition(), food.getSaturationModifier());
  for (Pair<MobEffectInstance,Float> pair : food.getEffects()) {
    if (!world.isClientSide() && pair.getFirst() != null && world.getRandom().nextFloat() < pair.getSecond()) {
      MobEffectInstance effect = new MobEffectInstance(pair.getFirst());
      // if adding, increase duration by current duration, provided its an exact level match
      if (combination == EffectCombination.ADD) {
        MobEffectInstance current = player.getEffect(effect.getEffect());
        if (current != null && current.getAmplifier() == effect.getAmplifier()) {
          effect.duration += current.getDuration();
        }
      }
      player.addEffect(effect);
    }
  }
  // remove one bite from the cake
  int i = state.getValue(BITES);
  if (i < 6) {
    world.setBlock(pos, state.setValue(BITES, i + 1), 3);
  } else {
    world.removeBlock(pos, false);
  }
  return InteractionResult.SUCCESS;
}

private boolean hasAllEffects(Player player) {
  for (Pair<MobEffectInstance,Float> pair : food.getEffects()) {
    if (pair.getFirst() != null) {
      MobEffectInstance current = player.getEffect(pair.getFirst().getEffect());
      if (current == null || current.getDuration() < 100) {
        return false;
      }
    }
  }
  return true;
}

public static FoodProperties getCake(FoliageType slime) {
  return switch (slime) {
    default -> EARTH_CAKE;
    case SKY -> SKY_CAKE;
    case ICHOR -> ICHOR_CAKE;
    case BLOOD -> BLOOD_CAKE;
    case ENDER -> ENDER_CAKE;
  };
}

static {
  BlockBehaviour.Properties CAKE = builder(SoundType.WOOL).forceSolidOn().strength(0.5F).sound(SoundType.WOOL).pushReaction(PushReaction.DESTROY);
  cake = BLOCKS.registerEnum(FoliageType.values(), "cake", type -> {
    if (type == FoliageType.ICHOR) {
      return new InvertedCakeBlock(CAKE, TinkerFood.ICHOR_CAKE, EffectCombination.BLOCK);
    }
    return new FoodCakeBlock(CAKE, TinkerFood.getCake(type), type == FoliageType.ENDER ? EffectCombination.ADD : EffectCombination.BLOCK);
  }, UNSTACKABLE_BLOCK_ITEM);
  magmaCake = BLOCKS.register("magma_cake", () -> new FoodCakeBlock(CAKE, TinkerFood.MAGMA_CAKE, EffectCombination.BLOCK), UNSTACKABLE_BLOCK_ITEM);
}

public ReturningTeleportEvent(LivingEntity entity, double targetX, double targetY, double targetZ) {
  super(entity, targetX, targetY, targetZ);
}

public static boolean tryTeleport(EntityTeleportEvent event) {
  MinecraftForge.EVENT_BUS.post(event);
  if (!event.isCanceled()) {
    // spawn particles at old location
    Entity entity = event.getEntity();
    spawnParticles(entity);

    // this logic only runs serverside, so need to use the server controller logic to move the player
    if (entity instanceof ServerPlayer playerMP) {
      playerMP.connection.teleport(event.getTargetX(), event.getTargetY(), event.getTargetZ(), playerMP.getYRot(), playerMP.getXRot(), PACKET_FLAGS);
    } else {
      entity.setPos(event.getTargetX(), event.getTargetY(), event.getTargetZ());
    }
    // particles at new location
    spawnParticles(entity);
    entity.level().playSound(null, entity.getX(), entity.getY(), entity.getZ(), Sounds.ENDERPORTING.getSound(), entity.getSoundSource(), 1f, 1f);
    return true;
  }
  return false;
}

private static void spawnParticles(Entity entity) {
  Level level = entity.level();
  if (level instanceof ServerLevel serverWorld) {
    for (int i = 0; i < 32; ++i) {
      serverWorld.sendParticles(ParticleTypes.PORTAL, entity.getX(), entity.getY() + level.random.nextDouble() * 2.0D, entity.getZ(), 1, level.random.nextGaussian(), 0.0D, level.random.nextGaussian(), 0);
    }
  }
}

public static ModDataNBT getOrWarn(Entity entity) {
  Optional<ModDataNBT> data = entity.getCapability(CAPABILITY).resolve();
  if (data.isEmpty()) {
    TConstruct.LOG.warn("Missing Tinkers NBT on entity {}, this should not happen", entity.getType());
    return new ModDataNBT();
  }
  return data.get();
}

private static void playerClone(PlayerEvent.Clone event) {
  Player original = event.getOriginal();
  original.reviveCaps();
  original.getCapability(CAPABILITY).ifPresent(oldData -> {
    CompoundTag nbt = oldData.getCopy();
    if (!nbt.isEmpty()) {
      event.getEntity().getCapability(CAPABILITY).ifPresent(newData -> newData.copyFrom(nbt));
    }
  });
  original.invalidateCaps();
}

